# Bilingual customer copy. Source links and review tracking are stored separately.
COPY={}
def page(id,en,es,sections_en,sections_es,check_en=None,check_es=None):
 COPY[f'DD-{id:03d}']={'en':{'title':en[0],'intro':en[1],'sections':sections_en,'checklist':check_en or []},'es':{'title':es[0],'intro':es[1],'sections':sections_es,'checklist':check_es or []}}
page(1,('A better life with your Doberman.','Practical guides for the first days, everyday routines and the small training moments that build a good life together.'),('Una buena vida con tu dóberman.','Guías prácticas para los primeros días, las rutinas diarias y los pequeños momentos de aprendizaje que os ayudan a vivir mejor juntos.'),[('Start where you are','Bringing a puppy home? Begin with the first-week plan and supplies checklist. Already sharing your home with a Doberman? Explore temperament, owner readiness and training foundations. You do not need to solve everything at once. Choose the question that matters today, then take one manageable next step.'),('Understand your dog, then build your routine','A breed description is a starting point, not a prediction of an individual dog. Pay attention to what your dog enjoys, what makes them uncomfortable and how they recover after activity. A predictable home, a place to rest and patient teaching are useful foundations at every stage.'),('Useful guidance, clear boundaries','Our guides focus on decisions you can make at home: preparing a safe space, keeping an observation log and practicing simple skills. Questions about illness, distress or an individual dog’s treatment belong with the appropriate veterinary or behavior professional.')],[('Empieza por tu situación','¿Vas a recibir a un cachorro? Empieza por el plan de la primera semana y la lista de material. Si ya convives con un dóberman, explora su temperamento, la preparación del hogar y las bases del adiestramiento. No hace falta resolverlo todo de golpe. Elige la pregunta que importa hoy y da un paso manejable.'),('Conoce a tu perro y crea una rutina','La descripción de una raza orienta, pero no predice cómo será cada perro. Observa qué disfruta, qué le incomoda y cómo se recupera después de una actividad. Un hogar previsible, un lugar de descanso y una enseñanza paciente son buenas bases en cualquier etapa.'),('Orientación útil y límites claros','Nuestras guías se centran en decisiones domésticas: preparar un espacio seguro, llevar un registro y practicar habilidades sencillas. Las dudas sobre enfermedad, angustia o tratamiento individual deben consultarse con el profesional veterinario o de comportamiento adecuado.')])
page(2,('Is a Doberman right for your life?','Look beyond appearance. Consider the time, teaching, household setup and support you can offer an individual dog.'),('¿Encaja un dóberman en tu vida?','Mira más allá de su aspecto. Valora el tiempo, la enseñanza, la organización del hogar y el apoyo que puedes ofrecer a cada perro.'),[('Breed tendencies are not guarantees','The AKC describes the Doberman as intelligent and vigilant. Those broad descriptions cannot tell you whether a particular dog will be comfortable with visitors, other animals or time alone. Ask about that dog’s history and observe their behavior in context.'),('Make the household plan concrete','Decide who handles meals, toilet opportunities, rest and training. Identify safe separation spaces before introductions to children or other animals. A large garden does not replace interaction, observation or a workable daily routine.'),('Choose your next question','If this is your first dog, use the readiness checklist before buying equipment. If you are preparing for a puppy, start with the first week. If daily life feels chaotic, organize a simple schedule and reward-based practice before adding harder goals.')],[('Las tendencias de raza no son garantías','El AKC describe al dóberman como inteligente y atento. Esas características generales no permiten saber si un perro concreto estará cómodo con visitas, otros animales o momentos a solas. Pregunta por su historia y observa su comportamiento en contexto.'),('Concreta el plan familiar','Acordad quién se ocupa de las comidas, las salidas para hacer sus necesidades, el descanso y el aprendizaje. Prepara espacios de separación seguros antes de presentar al perro a niños u otros animales. Un jardín grande no sustituye la interacción ni una rutina viable.'),('Elige tu siguiente pregunta','Si será tu primer perro, utiliza la lista de preparación antes de comprar material. Si esperas un cachorro, empieza por la primera semana. Si el día a día resulta caótico, organiza una rutina sencilla y práctica con recompensas antes de añadir objetivos más difíciles.')])
page(3,('Your Doberman puppy, one day at a time.','Prepare a calm arrival, a flexible routine and a home that makes good choices easier for your puppy.'),('Tu cachorro dóberman, día a día.','Prepara una llegada tranquila, una rutina flexible y un hogar que facilite las buenas decisiones de tu cachorro.'),[('Before your puppy arrives','Choose a resting area and a toilet route. Check gates, cables, small objects and cleaning supplies. Ask the breeder or rescue for the current food, routine and records so you can discuss changes with your veterinarian rather than guess.'),('The first week is about settling in','Keep introductions brief and give your puppy an easy way to retreat. Plan household cover around toilet opportunities and rest. Record what actually happens; that is more useful than expecting your puppy to follow a perfect timetable.'),('Teach everyday skills gently','Name response, voluntary entry into a resting space and comfortable handling can begin as easy games. Choose small goals and keep practice comfortable. Ask your veterinarian about local disease risks and suitable exposure opportunities before planning outings.')],[('Antes de la llegada','Elige una zona de descanso y un recorrido para salir a hacer sus necesidades. Revisa barreras, cables, objetos pequeños y productos de limpieza. Pide al criador o a la protectora información sobre la comida, la rutina y los documentos actuales para hablar de los cambios con tu veterinario.'),('La primera semana es para adaptarse','Haz presentaciones breves y permite que el cachorro se retire. Organiza el apoyo familiar alrededor de las salidas y del descanso. Registra lo que ocurre realmente; sirve más que exigir un horario perfecto.'),('Enseña las habilidades cotidianas con calma','Responder al nombre, entrar voluntariamente en una zona de descanso y aceptar un manejo cómodo pueden empezar como juegos fáciles. Elige objetivos pequeños. Consulta al veterinario los riesgos sanitarios locales y las exposiciones adecuadas antes de organizar salidas.')])
page(4,('Small steps. Better everyday training.','Choose one useful skill, practice in an easy setting and reward the behavior you want to see again.'),('Pasos pequeños para aprender mejor.','Elige una habilidad útil, practica en un entorno sencillo y recompensa la conducta que quieres que se repita.'),[('Start with the situation, not a label','“Stubborn” does not describe what a dog needs to learn. Write down the actual situation: your puppy walks away when called in the garden, or cannot settle while visitors arrive. That gives you a practical starting point for adjusting distance, distractions and rewards.'),('Keep the first repetition easy','Choose a quiet space and a reward your dog wants in that moment. Make the goal small enough to succeed. If practice falls apart, reduce the challenge rather than repeating a cue louder. The AVSAB recommends reward-based methods for training.'),('Practice a skill your day needs','Start with foundations, then choose potty training or a comfortable crate introduction if those matter to your household. Record a few repetitions and how your dog responded. A useful plan changes when observation shows the setup is too difficult.'),('Get help when safety or distress is involved','If a dog is frightened, guarding, biting or panicking when alone, seek qualified help rather than treating the concern as a simple obedience exercise. Ask a trainer how they protect welfare, adapt sessions and involve a veterinarian when needed.')],[('Empieza por la situación, no por una etiqueta','“Terco” no explica qué necesita aprender un perro. Describe lo que ocurre: se aleja cuando lo llamas en el jardín o no consigue descansar cuando llegan visitas. Así podrás ajustar la distancia, las distracciones y las recompensas.'),('Facilita la primera repetición','Elige un lugar tranquilo y una recompensa que le interese en ese momento. Plantea un objetivo pequeño y alcanzable. Si la práctica se complica, reduce la dificultad en vez de repetir la señal más fuerte. La AVSAB recomienda métodos basados en recompensas.'),('Practica algo útil para vuestro día','Empieza por las bases y después elige el aprendizaje para hacer sus necesidades fuera o la introducción al transportín, según vuestra situación. Registra algunas repeticiones y la respuesta del perro. Ajusta el plan cuando la observación muestre que resulta demasiado difícil.'),('Busca apoyo ante angustia o riesgos','Si el perro tiene miedo, protege recursos, muerde o entra en pánico al quedarse solo, busca ayuda cualificada. Pregunta al profesional cómo cuida el bienestar, adapta las sesiones y colabora con un veterinario cuando corresponde.')])
page(17,('Doberman temperament: understand the dog in front of you','Use breed information to prepare good questions. Use observation to understand your own dog.'),('Temperamento del dóberman: conoce a tu perro','Utiliza la información sobre la raza para preparar buenas preguntas y la observación para conocer a tu propio perro.'),[('Separate a description from a prediction','Breed descriptions can help you think about ownership responsibilities. They cannot guarantee a dog’s friendliness, confidence or suitability for a particular home. Age, health, learning history and the immediate situation all matter. Avoid choosing a dog on the assumption that a breed label will do the work of training or supervision.'),('Observe in ordinary moments','Notice how your dog responds when a visitor enters, an unfamiliar sound occurs or a game ends. Record the setting, the distance and what your dog did next. “Looked away and moved behind the sofa when the door opened” is more useful than “was being difficult.” Do not deliberately provoke a reaction to test temperament.'),('Give choices and predictable routines','Create a resting place that household members respect. Use barriers when you cannot supervise an introduction. Let visitors wait rather than crowd the dog. A dog who moves away needs space; a dog who approaches still needs a comfortable interaction rather than forced handling.'),('Match expectations to the individual','A dog who enjoys quiet sniffing walks may not enjoy a busy dog gathering. The useful question is whether an activity is comfortable and manageable for that dog. Build new experiences gradually and be willing to choose another setting. Appearance, sex or country of breeding cannot replace individual assessment.'),('Turn an observation into a next step','Choose one situation to make easier this week. For a busy doorway, arrange a resting space away from arrivals and practice when no visitors are present. For an unsettled puppy, simplify the daily routine. If behavior changes suddenly, or a situation involves distress or bite risk, seek professional assessment.')],[('Distingue descripción y predicción','La descripción de una raza ayuda a valorar responsabilidades. No garantiza la sociabilidad, la confianza ni la adaptación de un perro a una casa concreta. También importan la edad, la salud, la experiencia y la situación. Una etiqueta de raza no sustituye la enseñanza ni la supervisión.'),('Observa momentos cotidianos','Fíjate en lo que ocurre cuando entra una visita, se oye un ruido desconocido o termina un juego. Anota el lugar, la distancia y la respuesta. “Se apartó y se colocó detrás del sofá cuando abrimos la puerta” resulta más útil que “se portó mal”. No provoques una reacción para poner a prueba su temperamento.'),('Ofrece opciones y rutinas previsibles','Crea un lugar de descanso que todos respeten. Utiliza barreras cuando no puedas supervisar una presentación. Pide a las visitas que esperen sin rodear al perro. Si se aleja, necesita espacio; si se acerca, también necesita una interacción cómoda y sin manejo forzado.'),('Adapta las expectativas a cada perro','Un perro que disfruta paseos tranquilos olfateando quizá no disfrute una reunión concurrida. Lo importante es si la actividad resulta cómoda y manejable para él. Introduce experiencias gradualmente y cambia de entorno si hace falta. El aspecto, el sexo o el país de cría no sustituyen una valoración individual.'),('Convierte la observación en un paso concreto','Elige una situación que puedas facilitar esta semana. Si la entrada está muy concurrida, prepara una zona tranquila lejos de la puerta y practica sin visitas. Si el cachorro no descansa, simplifica la rutina. Ante un cambio repentino, angustia o riesgo de mordedura, solicita valoración profesional.')],['Record one comfortable situation and one difficult situation.','Write what happened without assigning motives.','Identify an easier setting or more distance.','Agree on supervision and resting-space rules.'],['Anota una situación cómoda y otra difícil.','Describe lo ocurrido sin atribuir intenciones.','Busca un entorno más sencillo o mayor distancia.','Acordad la supervisión y las normas de descanso.'])
page(18,('Your first Doberman: a realistic readiness checklist','A good match starts with a workable household plan—not just enthusiasm for the breed.'),('Tu primer dóberman: prepara un plan realista','Una buena convivencia empieza con un plan doméstico viable, además del entusiasmo por la raza.'),[('Look at an ordinary working week','Write down when someone is available for meals, toilet trips, companionship and teaching. Include commuting, weekends and changes to your schedule. If you cannot cover a puppy’s needs yourself, identify dependable support before the dog arrives. An arrangement that depends on everyone unexpectedly being free is not a plan.'),('Check the home you actually have','Assess entrances, stairs, secure separation areas and access to suitable outdoor spaces. Review landlord or building rules directly rather than assume a dog is allowed. Plan how you will supervise children and introductions to other animals. Decide where the dog can rest without being approached.'),('Plan expenses without a universal price tag','List food, routine veterinary care, equipment, training and paid care when needed. Add a separate contingency category. Obtain current local estimates and read insurance terms if you are considering a policy. Prices vary by location and individual needs, so a single online total cannot tell you what ownership will cost you.'),('Ask about the individual dog','For a rescue, ask how the dog responds to handling, visitors and time alone in known settings. For a puppy, ask about the raising environment and verifiable records. Avoid interpreting a sales promise as proof of temperament or future health. Make time for follow-up questions and professional input.'),('Make a decision you can sustain','If the plan has gaps, change the timing, organize support or consider whether another individual dog is a better match. Waiting can be a responsible decision. If you proceed, assign household roles and start with the supplies list and first-week plan. Revisit the arrangement when real observations replace assumptions.')],[('Revisa una semana laboral normal','Anota cuándo habrá alguien disponible para comidas, salidas, compañía y aprendizaje. Incluye desplazamientos, fines de semana y cambios de horario. Si necesitas ayuda para atender al cachorro, identifica apoyo fiable antes de su llegada. Depender de que todos estén libres por casualidad no es un plan.'),('Valora tu vivienda real','Revisa accesos, escaleras, zonas de separación y espacios exteriores adecuados. Consulta directamente las normas del alquiler o del edificio. Organiza la supervisión de niños y las presentaciones a otros animales. Decide dónde podrá descansar sin que lo molesten.'),('Calcula gastos con datos locales','Incluye comida, atención veterinaria habitual, material, aprendizaje y cuidados cuando estés fuera. Separa un fondo para imprevistos. Pide presupuestos actuales y lee las condiciones del seguro si lo estás considerando. Una cifra de internet no permite calcular el coste de tu perro en tu localidad.'),('Pregunta por el perro concreto','En una adopción, pregunta cómo responde al manejo, a las visitas y a estar solo en entornos conocidos. Para un cachorro, pide información sobre la crianza y documentos verificables. Una promesa comercial no demuestra su temperamento ni su salud futura. Reserva tiempo para preguntas y apoyo profesional.'),('Elige una decisión sostenible','Si el plan tiene huecos, ajusta el momento, organiza ayuda o valora otro perro que encaje mejor. Esperar puede ser responsable. Si sigues adelante, reparte las tareas y empieza por el material y la primera semana. Revisa el plan cuando las observaciones reales sustituyan las suposiciones.')],['Someone can cover the dog’s day-to-day needs.','Housing rules and safe separation are checked.','Routine and unexpected costs have a plan.','You know where to ask for veterinary and training support.'],['Hay alguien disponible para atender las necesidades diarias.','La vivienda permite perros y tiene zonas seguras.','Existe un plan para gastos habituales e imprevistos.','Sabes dónde solicitar apoyo veterinario y de aprendizaje.'])
page(26,('The first week home with your Doberman puppy','Keep the first week calm and predictable. Focus on rest, toilet opportunities and learning what helps your puppy feel comfortable.'),('La primera semana con tu cachorro dóberman','Mantén una llegada tranquila y previsible. Prioriza el descanso, las salidas y la observación de lo que ayuda a tu cachorro a sentirse cómodo.'),[('Prepare before the arrival','Set up a small, safe resting area and a simple route to the toilet location. Keep familiar food and records from the breeder or rescue available. Agree who will supervise and who will handle nighttime needs. Put cables, medicines, cleaning products and small objects out of reach before bringing the puppy inside.'),('Let the first day stay small','Introduce the resting area and toilet route without turning arrival into a gathering. Offer water and follow the existing feeding information while arranging your veterinary consultation. Give the puppy time to explore a manageable area. Visitors and extra activities can wait until you understand how the puppy is coping.'),('Build a rhythm from observations','Use a repeating pattern of toilet opportunity, appropriate activity and quiet rest. Watch for waking, transitions and changes in attention rather than relying only on a clock. Record meals, toilet trips and rest in a simple log. Share the log with everyone caring for the puppy so the next person knows what happened.'),('Introduce your resting space gently','Allow exploration with the door open if you are using a crate. Keep early experiences easy and pleasant; a crate is not a place to send a puppy as punishment. If the puppy shows distress, reassess the setup and get appropriate help instead of forcing longer confinement.'),('End the week with a useful review','Look at what worked: a quieter room, a different toilet route or a shorter practice session. Choose one adjustment for the following week. Arrange professional support for persistent distress or signs of illness. Ask your veterinarian about safe social exposure and the next medical-care decisions for this individual puppy.')],[('Prepara la casa antes de la llegada','Organiza una zona pequeña y segura para descansar y un recorrido sencillo hasta el lugar para hacer sus necesidades. Ten a mano la comida habitual y los documentos del criador o de la protectora. Acordad quién supervisará y atenderá la noche. Guarda cables, medicamentos, productos de limpieza y objetos pequeños.'),('Haz que el primer día sea sencillo','Presenta la zona de descanso y el recorrido de salida sin convertir la llegada en una reunión. Ofrece agua y sigue la información de alimentación habitual mientras organizas la consulta veterinaria. Permite explorar un espacio manejable. Las visitas y las actividades adicionales pueden esperar.'),('Crea un ritmo a partir de lo que observas','Alterna oportunidades para hacer sus necesidades, actividad adecuada y descanso tranquilo. Observa el despertar, los cambios de actividad y la atención, además de mirar el reloj. Lleva un registro sencillo de comidas, salidas y descanso. Compártelo para que cada cuidador sepa qué ha ocurrido.'),('Introduce el espacio de descanso con calma','Si utilizas un transportín, deja que lo explore con la puerta abierta. Las primeras experiencias deben ser fáciles y agradables; no lo uses como castigo. Si aparece angustia, revisa la organización y busca apoyo en vez de imponer encierros más largos.'),('Termina la semana con una revisión útil','Valora qué funcionó: una habitación tranquila, otra salida o una práctica más corta. Elige un ajuste para la semana siguiente. Busca ayuda si persiste la angustia o aparecen signos de enfermedad. Consulta al veterinario las exposiciones sociales seguras y las decisiones sanitarias para ese cachorro.')],['Prepare the resting area and toilet route.','Keep food history and veterinary records together.','Assign daytime and nighttime care.','Log what happens instead of chasing a perfect schedule.','Review one change at the end of the week.'],['Prepara el descanso y el recorrido de salida.','Reúne la información de comida y los documentos.','Reparte los cuidados diurnos y nocturnos.','Registra lo ocurrido sin exigir un horario perfecto.','Revisa un ajuste al terminar la semana.'])
page(27,('Doberman puppy supplies: buy what you need first','Start with safe, well-fitting essentials. Choose equipment for your puppy’s current size and your home, then reassess as they grow.'),('Material para un cachorro dóberman: lo esencial primero','Empieza con lo necesario, seguro y bien ajustado. Elige el material según su tamaño actual y tu hogar, y revísalo mientras crece.'),[('The arrival essentials','Prepare water and food bowls, the familiar food, identification, a suitable leash and well-fitting walking equipment. Add washable bedding and a safe resting setup. Before spending on extras, check that the puppy can rest, drink, move comfortably and reach the planned toilet area with supervision.'),('A resting area that fits','If you choose a crate, assess space for comfortable standing, turning and lying down. An adjustable divider can help with a growing puppy, but size is only one part of the decision: ventilation, secure construction and a gradual introduction matter too. A gated puppy-safe area can be useful when you need another supervised arrangement.'),('Choose toys for the way they are used','Think about supervised play, texture and size rather than buying a large pile of products. Inspect items for loose pieces and wear. Introduce one item at a time and watch how the puppy interacts with it. No toy label removes the need for observation; put away items that are damaged or unsuitable.'),('Prepare for everyday cleanup and handling','Keep washable covers, waste bags and a cleaning product suitable for the surface and intended use. Follow the label and keep chemicals away from the puppy. Have a soft grooming tool and a way to reward comfortable handling. Specialist products can wait until a professional or the dog’s actual needs justify them.'),('Separate essentials from later purchases','Decorative clothing, a second bed or specialist sport equipment do not need to be part of arrival day. Keep receipts and note measurements so you can check fit later. Spend first on a safe setup and dependable care. This is a selection checklist, not a claim that we tested particular brands.')],[('Lo necesario para la llegada','Prepara recipientes para agua y comida, el alimento habitual, identificación, una correa adecuada y equipo de paseo bien ajustado. Añade una cama lavable y una zona segura de descanso. Antes de comprar extras, comprueba que pueda beber, descansar, moverse cómodamente y llegar al lugar elegido para hacer sus necesidades.'),('Un espacio de descanso adecuado','Si eliges transportín, comprueba que pueda ponerse de pie, girarse y tumbarse cómodamente. Un separador ajustable puede servir durante el crecimiento, pero también importan la ventilación, la construcción segura y una introducción gradual. Una zona protegida con barrera puede ser otra opción supervisada.'),('Elige juguetes según su uso','Valora el juego supervisado, la textura y el tamaño en vez de acumular productos. Revisa piezas sueltas y desgaste. Presenta un objeto cada vez y observa cómo lo usa. Ninguna etiqueta elimina la necesidad de supervisión; retira lo dañado o inadecuado.'),('Prepara la limpieza y el manejo diario','Ten fundas lavables, bolsas y un limpiador adecuado para la superficie y el uso previsto. Sigue la etiqueta y guarda los productos lejos del cachorro. Prepara un utensilio suave de higiene y recompensas para un manejo cómodo. Los productos especializados pueden esperar a que exista una necesidad real.'),('Distingue lo esencial de lo que puede esperar','La ropa decorativa, otra cama o el material deportivo especializado no son necesarios el primer día. Guarda recibos y medidas para revisar el ajuste. Prioriza la seguridad y los cuidados fiables. Esta guía ofrece criterios de selección, sin afirmar pruebas de marcas concretas.')],['Water and food bowls; familiar food.','Identification, leash and fitted walking equipment.','Washable bedding and a safe rest area.','Suitable supervised toys and cleanup supplies.','A plan to check equipment fit as the puppy grows.'],['Recipientes de agua y comida; alimento habitual.','Identificación, correa y equipo de paseo ajustado.','Cama lavable y descanso seguro.','Juguetes supervisados y material de limpieza.','Un plan para revisar el ajuste durante el crecimiento.'])
page(28,('A flexible daily schedule for your Doberman puppy','Build your day around what happens next: waking, meals, toilet opportunities, comfortable activity and rest. Adjust the clock to your puppy.'),('Una rutina flexible para tu cachorro dóberman','Organiza el día alrededor del despertar, las comidas, las salidas, la actividad cómoda y el descanso. Ajusta el reloj a tu cachorro.'),[('Plan a sequence before fixed times','Write a short sequence you can repeat: wake, toilet opportunity, a meal when scheduled, suitable activity and quiet rest. Your puppy’s response is the important feedback. A sample schedule is an organizational example, not a promise about bladder control, sleep hours or feeding requirements.'),('A morning example','When the puppy wakes, offer the planned toilet opportunity. Follow with the meal arrangements you have agreed with your veterinarian and the puppy’s existing care information. Keep an easy activity brief, then offer another toilet opportunity and quiet rest. Adjust the order to what you observe rather than making the puppy wait for an arbitrary time.'),('Arrange the middle of the day','Plan who is available when the puppy wakes or needs supervision. If your work hours leave a gap, arrange dependable care instead of expecting a crate to solve it. Combine gentle interaction with opportunities to rest. Keep household handovers simple: note the last meal, toilet trip and any concern.'),('Make the evening easier','Avoid packing every missed activity into the final hour. Choose a manageable interaction, check the resting space and prepare for nighttime toilet needs. Keep handling calm. A busy household can use a written plan to prevent several people repeatedly waking or exciting the puppy.'),('Review patterns, not one bad day','Log what happened for several ordinary days: approximate times, activities and the puppy’s response. Look for gaps in supervision or signs that the setup is too demanding. Discuss persistent concerns with a veterinarian or qualified trainer. Change one variable at a time so you can see whether the adjustment helps.')],[('Planifica una secuencia antes que horas exactas','Escribe un patrón repetible: despertar, oportunidad para hacer sus necesidades, comida cuando corresponda, actividad adecuada y descanso. La respuesta del cachorro es la referencia principal. Un ejemplo organiza el día, pero no garantiza control de esfínteres, horas de sueño ni necesidades alimentarias.'),('Un ejemplo de mañana','Al despertar, ofrece la salida prevista. Después sigue la organización de comidas acordada con el veterinario y la información de cuidados habitual. Realiza una actividad sencilla y breve, ofrece otra oportunidad para hacer sus necesidades y facilita el descanso. Ajusta el orden a lo que observes.'),('Organiza las horas centrales','Acordad quién estará disponible cuando despierte o necesite supervisión. Si el trabajo deja un hueco, organiza cuidados fiables en vez de esperar que el transportín lo resuelva. Alterna interacción suave y descanso. Anota la última comida, salida y cualquier preocupación para facilitar los relevos.'),('Simplifica la tarde y la noche','No concentres todas las actividades pendientes en la última hora. Elige una interacción manejable, revisa el descanso y prepara las salidas nocturnas. Mantén un manejo tranquilo. Un plan escrito evita que varias personas despierten o exciten repetidamente al cachorro.'),('Revisa patrones, no un día difícil','Durante varios días normales anota horas aproximadas, actividades y respuestas. Busca huecos de supervisión o señales de que la organización exige demasiado. Consulta las preocupaciones persistentes. Cambia una variable cada vez para valorar si el ajuste resulta útil.')],['Morning: toilet opportunity, planned meal, easy activity, rest.','Daytime: cover supervision and handovers.','Evening: comfortable interaction and a quiet resting setup.','Record actual events; adjust the pattern.'],['Mañana: salida, comida prevista, actividad sencilla y descanso.','Día: organiza la supervisión y los relevos.','Noche: interacción cómoda y un descanso tranquilo.','Anota lo ocurrido y ajusta el patrón.'])
page(34,('Reward-based training foundations for your Doberman','Make the right choice easy, notice it clearly and offer something your dog values. Start in a setting where both of you can succeed.'),('Bases del adiestramiento con recompensas para tu dóberman','Facilita la conducta que buscas, señálala con claridad y ofrece algo que tu perro valore. Empieza en un entorno sencillo para ambos.'),[('Define a behavior you can observe','Replace “be good” with a small goal, such as looking toward you when you say the dog’s name in a quiet room. Decide what counts as a successful repetition before practice begins. Clear criteria help you avoid moving the goal while the dog is trying to learn.'),('Choose a reward for this moment','A small suitable food reward, access to a toy or an enjoyable activity may be useful depending on the dog and setting. Observe whether the dog actually wants it. Food rewards are part of the overall diet; ask your veterinarian about individual restrictions rather than relying on a universal allowance.'),('Make the feedback clear','For an easy orientation game, wait for the dog to turn toward you, use one consistent marker such as “yes,” then offer the reward. Keep the response simple and predictable. Practice without adding noise or extra demands. A marker should help identify the behavior, not become a repeated cue that confuses the task.'),('Change only one challenge at a time','Once a task is comfortable, try a modest change to distance, setting or distraction. If the dog cannot respond, return to an easier version. Keep practice brief enough that the dog stays comfortable and interested. End with an achievable repetition rather than pushing until attention disappears.'),('Use observation to troubleshoot','If the dog turns away, check the environment, reward and difficulty. Record what happened rather than assign blame. The AVSAB’s humane training statement supports reward-based methods. Seek individualized help when a concern involves fear, pain, aggression or persistent distress; a simple practice game does not replace assessment.')],[('Define una conducta observable','Sustituye “pórtate bien” por un objetivo pequeño, como mirarte al oír su nombre en una habitación tranquila. Decide de antemano qué cuenta como una repetición correcta. Así no cambiarás la exigencia mientras el perro intenta aprender.'),('Elige una recompensa para ese momento','Según el perro y el entorno, puede servir una pequeña recompensa alimentaria adecuada, un juguete o una actividad agradable. Observa si realmente le interesa. Las recompensas alimentarias forman parte de la dieta; consulta las restricciones individuales al veterinario en vez de usar una cantidad universal.'),('Da una respuesta clara','En un juego sencillo de atención, espera a que se vuelva hacia ti, utiliza un marcador constante como “sí” y después ofrece la recompensa. Mantén la secuencia simple y previsible. No añadas ruido ni exigencias. El marcador ayuda a identificar la conducta, no debe convertirse en una señal repetida que confunda.'),('Cambia una dificultad cada vez','Cuando la tarea resulte cómoda, introduce un cambio pequeño de distancia, lugar o distracción. Si no responde, vuelve a una versión más fácil. Haz prácticas breves mientras siga cómodo e interesado. Termina con una repetición alcanzable en vez de alargarla hasta perder su atención.'),('Resuelve las dificultades observando','Si se aparta, revisa el entorno, la recompensa y la dificultad. Anota lo ocurrido sin culparlo. La declaración de adiestramiento humanitario de la AVSAB respalda los métodos con recompensas. Ante miedo, dolor, agresividad o angustia persistente, busca apoyo individualizado.')],['Name the exact behavior.','Choose an easy setting and suitable reward.','Mark the behavior, then reward.','Change one difficulty at a time.','Record what helped and when you stopped.'],['Define la conducta concreta.','Elige un entorno sencillo y una recompensa adecuada.','Marca la conducta y después recompensa.','Cambia una dificultad cada vez.','Anota qué ayudó y cuándo terminaste.'])
page(35,('Potty training your Doberman puppy','Offer frequent chances to use the chosen toilet area, reward success and organize supervision so accidents become useful feedback—not a reason to punish.'),('Enseña a tu cachorro dóberman dónde hacer sus necesidades','Ofrece oportunidades frecuentes en el lugar elegido, recompensa los aciertos y organiza la supervisión. Los accidentes sirven para ajustar el plan, no para castigar.'),[('Choose an accessible toilet location','Pick a location you can reach promptly and use consistently. Ask your veterinarian about local disease risks before deciding where a young puppy should go. If an indoor arrangement is necessary, make it clear and manageable, and plan how it fits your longer-term goal.'),('Watch transitions and your puppy’s signals','Offer opportunities around waking and changes in activity, as well as the puppy’s observed needs. Do not make the puppy wait simply because a timetable says the next trip is later. Note patterns in a log and use them to improve supervision. Avoid treating age-based holding formulas as a guarantee.'),('Reward the right location','When the puppy finishes in the chosen area, give an appropriate reward promptly. Keep the trip calm enough that the puppy can focus on the task. If nothing happens, return to supervised space and reassess when another opportunity is needed. Repeating a phrase louder does not create bladder control.'),('Handle an accident without blame','Clean the area with a suitable product according to the label and review what preceded the accident. Was supervision missing? Was the route difficult? Had the puppy just woken? Do not punish or rub the puppy’s nose in the mess. Adjusting the setup helps you create another chance for success.'),('Separate learning from a health concern','Keep a simple record of toilet opportunities, successes and accidents. Ask a veterinarian about persistent difficulty, discomfort or an unexpected change. An observation log helps explain the pattern but cannot diagnose the cause. If health concerns are excluded, a qualified trainer can help you refine the routine.')],[('Elige un lugar accesible','Busca un lugar al que puedas llegar con rapidez y utilizar de forma constante. Consulta al veterinario los riesgos sanitarios locales antes de elegir dónde llevará un cachorro pequeño. Si necesitas una zona interior, hazla clara y manejable y valora cómo encaja con el objetivo a largo plazo.'),('Observa las transiciones y sus señales','Ofrece oportunidades al despertar y al cambiar de actividad, además de atender sus necesidades observadas. No lo hagas esperar porque el horario marque una salida posterior. Registra patrones para mejorar la supervisión. Las fórmulas según la edad no garantizan cuánto puede aguantar.'),('Recompensa el lugar correcto','Cuando termine en la zona elegida, ofrece pronto una recompensa adecuada. Mantén la salida tranquila. Si no ocurre nada, vuelve a un espacio supervisado y valora cuándo necesita otra oportunidad. Repetir una frase más fuerte no crea control de esfínteres.'),('Gestiona un accidente sin culpar','Limpia con un producto adecuado siguiendo la etiqueta y revisa lo que ocurrió antes. ¿Faltó supervisión? ¿Era difícil salir? ¿Acababa de despertar? No lo castigues ni acerques su hocico al suelo sucio. Ajusta la organización para crear otra oportunidad de acertar.'),('Distingue aprendizaje y salud','Lleva un registro de oportunidades, aciertos y accidentes. Consulta las dificultades persistentes, molestias o cambios inesperados. El registro ayuda a explicar el patrón, pero no diagnostica. Si se descartan problemas sanitarios, un profesional cualificado puede ayudarte a mejorar la rutina.')],['Log: approximate time, preceding activity, opportunity and outcome.','Keep the toilet route simple.','Reward success in the chosen location.','Review supervision after an accident.','Ask for assessment when the pattern changes unexpectedly.'],['Registra hora aproximada, actividad previa, oportunidad y resultado.','Facilita el recorrido hasta la zona elegida.','Recompensa los aciertos en ese lugar.','Revisa la supervisión tras un accidente.','Consulta los cambios inesperados del patrón.'])
page(36,('Introduce a crate at your Doberman’s pace','A crate should become a comfortable resting option through gradual, voluntary experiences. It should never substitute for care, toilet opportunities or help with distress.'),('Introduce el transportín al ritmo de tu dóberman','El transportín puede ser una opción cómoda de descanso mediante experiencias graduales y voluntarias. No sustituye los cuidados, las salidas ni la ayuda ante la angustia.'),[('Check the space before you begin','Choose a secure, ventilated setup with room to stand, turn and lie comfortably. Inspect bedding and accessories for suitability and supervise their use. Position the crate where the dog can rest without constant interruptions. Decide on another safe arrangement if your dog cannot yet relax there.'),('Start with the door open','Let the dog investigate without being pushed inside. Place a suitable reward where it can be reached comfortably and allow the dog to leave. Repeat easy experiences without immediately adding a closed door. The important observation is whether the dog chooses to approach and remains comfortable.'),('Introduce changes in small steps','When open-door experiences are comfortable, make a small change and observe the response. A brief door movement is a different task from closing it, and closing it is different from moving away. Change one aspect at a time. Return to an easier step if the dog becomes uneasy rather than testing how long they can tolerate it.'),('Read comfort, not just silence','A quiet dog is not automatically a relaxed dog. Look at the whole response and whether the dog can engage comfortably, rest or choose to re-enter. If there is persistent vocalizing, escape behavior or obvious distress, stop increasing the challenge and seek qualified help. Do not use confinement to force a puppy to endure unmet toilet needs.'),('Fit the crate into a wider care plan','Arrange supervision, companionship and toilet opportunities around the individual dog. Do not use the crate as punishment or as a fix for separation distress. Keep notes on the setup, what changed and how your dog responded. Discuss concerns with a veterinarian or qualified reward-based professional before extending confinement.')],[('Revisa el espacio antes de empezar','Elige una estructura segura y ventilada con espacio para ponerse de pie, girarse y tumbarse cómodamente. Revisa la cama y los accesorios y supervisa su uso. Coloca el transportín donde pueda descansar sin interrupciones constantes. Prepara otra opción segura si todavía no consigue relajarse allí.'),('Empieza con la puerta abierta','Permite explorar sin empujar al perro dentro. Coloca una recompensa adecuada a una distancia cómoda y deja que salga. Repite experiencias fáciles antes de añadir el cierre. Lo importante es si decide acercarse y se mantiene cómodo.'),('Introduce cambios pequeños','Cuando esté cómodo con la puerta abierta, cambia un detalle y observa. Mover brevemente la puerta no es lo mismo que cerrarla, y cerrarla no es lo mismo que alejarte. Modifica un aspecto cada vez. Si aparece incomodidad, vuelve a un paso sencillo en vez de comprobar cuánto aguanta.'),('Observa comodidad, no solo silencio','Un perro callado no está necesariamente relajado. Valora la respuesta completa y si puede participar, descansar o volver a entrar voluntariamente. Ante vocalización persistente, intentos de escapar o angustia evidente, deja de aumentar la dificultad y busca apoyo. No utilices el encierro para imponer necesidades de higiene sin atender.'),('Integra el transportín en los cuidados','Organiza supervisión, compañía y salidas según el perro. No lo uses como castigo ni como solución a la angustia por separación. Anota la organización, los cambios y las respuestas. Consulta al veterinario o a un profesional cualificado antes de prolongar el encierro.')],['Safe fit, ventilation and placement.','Voluntary investigation with the door open.','One small change at a time.','Record comfortable behavior and reasons to pause.','Provide an alternative safe resting area.'],['Ajuste, ventilación y ubicación seguros.','Exploración voluntaria con la puerta abierta.','Un cambio pequeño cada vez.','Anota la comodidad y los motivos para parar.','Ofrece otra zona segura de descanso.'])
# Supporting trust pages: actual contact, practices and service boundaries.
page(15,('About Doberman Deals','A practical place to start when you are preparing for a Doberman or building better everyday routines.'),('Sobre Doberman Deals','Un punto de partida práctico para preparar la llegada de un dóberman y mejorar las rutinas cotidianas.'),[('What you will find here','Our guides bring together owner checklists, everyday examples and links to relevant source material. Start with a question you need to answer now, then follow the connected guides as your needs change.'),('How to use our guidance','These pages provide general education. They cannot assess your dog’s health, behavior or suitability from a distance. Seek individual professional help when the situation requires it.'),('Get in touch','Questions, corrections and accessibility feedback can be sent to dobermandeals3@gmail.com. Tell us which page you mean and what would make it more useful.')],[('Qué encontrarás','Reunimos listas prácticas, ejemplos cotidianos y enlaces a fuentes relevantes. Empieza por la pregunta que necesitas resolver y sigue las guías relacionadas cuando cambien tus necesidades.'),('Cómo utilizar las guías','Estas páginas ofrecen educación general. No permiten valorar a distancia la salud, el comportamiento ni la adaptación de tu perro. Busca apoyo profesional individualizado cuando corresponda.'),('Contacta con nosotros','Envía dudas, correcciones y comentarios de accesibilidad a dobermandeals3@gmail.com. Indica la página y qué la haría más útil.')])
page(121,('Our editorial approach','Useful guidance starts with a clear question, identifiable sources and an honest explanation of its limits.'),('Nuestro enfoque editorial','Una guía útil parte de una pregunta clara, fuentes identificables y una explicación honesta de sus límites.'),[('Evidence and everyday usefulness','We distinguish general owner examples from factual claims that need a source. Breed information should not be presented as a guarantee about an individual dog. Examples and checklists help you organize decisions; they do not provide a diagnosis.'),('Sources and assistance','We link relevant sources so you can read the original guidance. Writing and translation tools may assist with preparation. Their output does not count as professional advice or independent expert approval.'),('Corrections and commercial relationships','Send corrections to our contact address with the page and relevant evidence. Commercial relationships should be disclosed close to recommendations. A product mention is not proof of hands-on testing or endorsement.')],[('Evidencia y utilidad cotidiana','Distinguimos ejemplos para propietarios y afirmaciones que necesitan una fuente. La información de raza no garantiza cómo será cada perro. Los ejemplos y las listas ayudan a organizar decisiones, sin ofrecer diagnósticos.'),('Fuentes y herramientas','Enlazamos fuentes relevantes para consultar la orientación original. Las herramientas de escritura y traducción pueden ayudar a preparar contenido. Sus resultados no equivalen a consejo profesional ni a aprobación experta independiente.'),('Correcciones y relaciones comerciales','Envía correcciones indicando la página y la evidencia. Las relaciones comerciales deben explicarse junto a las recomendaciones. Mencionar un producto no demuestra que se haya probado ni que esté avalado.')])
page(122,('Understanding our review process','Look at the sources and the scope of a guide before applying it to your own dog.'),('Cómo entender nuestro proceso de revisión','Revisa las fuentes y el alcance de una guía antes de aplicarla a tu perro.'),[('General guidance and professional review','An educational guide cannot replace an assessment by your veterinarian or an appropriate behavior professional. A professional review, where shown, should identify the reviewer and the relevant credentials. Do not assume that every page has received that review.'),('What an updated date means','An updated date describes a change to the page. It does not guarantee that every linked resource remains current or that guidance suits an individual dog. Check the original source and ask for professional input when your situation is different.'),('Help us improve a page','Point out unclear advice, inaccessible content or a source that has changed. Include the page address and enough detail to explain the issue. Our contact page provides the route for feedback.')],[('Orientación general y revisión profesional','Una guía educativa no sustituye la valoración de tu veterinario o del profesional de comportamiento adecuado. Cuando se indique revisión profesional, debe identificarse a quien revisó y sus credenciales. No supongas que todas las páginas la tienen.'),('Qué significa la fecha de actualización','La fecha refleja un cambio en la página. No garantiza que cada recurso enlazado siga vigente ni que la orientación se ajuste a tu perro. Comprueba la fuente original y solicita apoyo cuando tu situación sea distinta.'),('Ayúdanos a mejorar','Comunica orientaciones poco claras, barreras de accesibilidad o fuentes que hayan cambiado. Incluye la dirección de la página y detalles suficientes. La página de contacto ofrece el canal para comentarios.')])
page(124,('Contact Doberman Deals','Have a question about a guide, spotted an error or need help using the site? Send us a message.'),('Contacta con Doberman Deals','¿Tienes una duda, has encontrado un error o necesitas ayuda para utilizar la web? Escríbenos.'),[('Email us','Write to dobermandeals3@gmail.com. For a correction, include the page address, the information you believe needs changing and a relevant source if available.'),('Protect your personal information','Please avoid sending medical records, payment details, passwords or information about other people. A short explanation of your website question is usually enough.'),('For your dog’s care','This inbox is not an emergency service or a veterinary consultation. Contact your veterinarian or local emergency veterinary provider if your dog needs urgent care.')],[('Escríbenos por correo','Contacta en dobermandeals3@gmail.com. Para una corrección, incluye la dirección de la página, la información que debería cambiar y una fuente relevante si la tienes.'),('Cuida tus datos personales','Evita enviar historiales médicos, información de pago, contraseñas o datos de otras personas. Normalmente basta con una explicación breve de la consulta sobre la web.'),('Para los cuidados de tu perro','Este correo no es un servicio de urgencias ni una consulta veterinaria. Si tu perro necesita atención urgente, contacta con tu veterinario o un servicio veterinario de urgencias local.')])
page(125,('Affiliate disclosure','You should be able to understand when a recommendation has a commercial relationship.'),('Información sobre afiliación','Debes poder reconocer cuándo una recomendación tiene una relación comercial.'),[('Commercial links','If a link earns us a commission, that relationship should be identified near the recommendation. A commission does not establish that a product suits your dog.'),('What these guides contain','The first puppy and training guides offer selection criteria and practical examples rather than ranked product reviews. They do not claim hands-on testing of particular brands.'),('Ask about a recommendation','If a relationship or claim is unclear, contact us with the page address and the link you mean. Read product instructions and verify current specifications before choosing equipment.')],[('Enlaces comerciales','Cuando un enlace nos permita recibir una comisión, esa relación debe explicarse junto a la recomendación. Una comisión no demuestra que el producto sea adecuado para tu perro.'),('Qué contienen estas guías','Las primeras guías de cachorros y aprendizaje ofrecen criterios prácticos, sin clasificaciones de productos ni afirmaciones de pruebas de marcas concretas.'),('Consulta una recomendación','Si una relación o afirmación no está clara, contacta indicando la página y el enlace. Lee las instrucciones y verifica las especificaciones actuales antes de elegir material.')])
page(126,('Privacy notice','Here is how website visits, email contact and optional waitlist signups are handled.'),('Aviso de privacidad','Así se gestionan las visitas, el contacto por correo y las inscripciones opcionales a la lista de novedades.'),[('Website measurement','The public website uses Google Analytics 4 through Google Tag Manager and Cloudflare Web Analytics to measure visits and interactions. Our preview website excludes the production Google tracking setup. Google and Cloudflare may process technical information under their own policies. We do not send signup email addresses or free-text dog-care answers in our analytics events.'),('Optional launch updates','The existing waitlist stores an email address, chosen language, agreement to launch updates and the signup date in Cloudflare. Turnstile helps protect the form against automated abuse. A signup is for updates, not a purchase. You can email us to request removal or stop receiving updates.'),('Email and your choices','Information you include in an email is used to handle the request. Send only what is necessary. Contact dobermandeals3@gmail.com for questions or requests about your information. Browser privacy settings and the providers’ policies give additional information about their services.')],[('Medición de visitas','La web pública utiliza Google Analytics 4 mediante Google Tag Manager y Cloudflare Web Analytics para medir visitas e interacciones. Nuestra web de vista previa excluye el seguimiento de producción de Google. Google y Cloudflare pueden procesar información técnica según sus políticas. No enviamos correos de inscripción ni respuestas libres sobre cuidados en nuestros eventos analíticos.'),('Novedades opcionales','La lista de novedades existente guarda el correo, el idioma elegido, el consentimiento a recibir avisos y la fecha de inscripción en Cloudflare. Turnstile ayuda a proteger el formulario contra abusos automatizados. Inscribirse permite recibir novedades, sin realizar una compra. Puedes solicitar la retirada por correo.'),('Correo y opciones personales','La información de tus mensajes se utiliza para atender la solicitud. Envía únicamente lo necesario. Contacta en dobermandeals3@gmail.com para preguntas o solicitudes sobre tus datos. Los ajustes del navegador y las políticas de los proveedores ofrecen información adicional.')])
page(127,('Using Doberman Deals','Use these guides as general education and a starting point for your own questions.'),('Uso de Doberman Deals','Utiliza estas guías como educación general y punto de partida para tus preguntas.'),[('Scope of the information','The site cannot assess your dog or replace veterinary, behavior, legal or financial advice for your circumstances. Examples are illustrative. Verify facts and current requirements that affect a decision.'),('External resources and images','Links take you to independent sources whose content and availability may change. Photographs retain their stated licenses and credits. Those credits do not imply that the photographer endorses this site.'),('Questions and corrections','Contact us if something is unclear or inaccurate. Optional launch updates do not create a purchase or guarantee future product availability. Read any actual offer terms before making a purchase.')],[('Alcance de la información','La web no puede valorar a tu perro ni sustituir consejo veterinario, de comportamiento, legal o financiero individualizado. Los ejemplos son ilustrativos. Verifica los datos y los requisitos actuales que afecten a una decisión.'),('Recursos e imágenes externas','Los enlaces llevan a fuentes independientes cuyo contenido y disponibilidad pueden cambiar. Las fotografías conservan sus licencias y créditos. El crédito no implica que su autor avale esta web.'),('Preguntas y correcciones','Contacta si algo resulta poco claro o incorrecto. Las novedades opcionales no constituyen una compra ni garantizan productos futuros. Lee las condiciones de una oferta real antes de comprar.')])

for lang in ('en','es'):
 COPY['DD-126'][lang]['sections'].append(('Contact messages' if lang=='en' else 'Mensajes de contacto', 'The contact form collects your email, inquiry category, message, language, consent and submission time. Messages are stored in Cloudflare for up to 30 days; staging test messages expire after 24 hours. Turnstile checks submissions. Message text and email are not sent as analytics event parameters. Contact us by email about your information.' if lang=='en' else 'El formulario recoge correo, categoría, mensaje, idioma, consentimiento y fecha. Los mensajes se guardan en Cloudflare hasta 30 días; pruebas de staging caducan tras 24 horas. Turnstile comprueba los envíos. Mensaje y correo no se envían como parámetros de analítica. Escríbenos por correo para consultar tus datos.'))
